class _MinHeap {
    constructor() { this.a = []; }
    size() { return this.a.length; }
    peek() { return this.a[0]; }
    push(x) {
        const a = this.a;
        a.push(x);
        let i = a.length - 1;
        while (i > 0) {
            const p = (i - 1) >> 1;
            if (a[p] <= a[i]) break;
            [a[p], a[i]] = [a[i], a[p]];
            i = p;
        }
    }
    pop() {
        const a = this.a;
        const top = a[0];
        const last = a.pop();
        if (a.length) {
            a[0] = last;
            let i = 0;
            const n = a.length;
            while (true) {
                let l = 2 * i + 1, r = 2 * i + 2, s = i;
                if (l < n && a[l] < a[s]) s = l;
                if (r < n && a[r] < a[s]) s = r;
                if (s === i) break;
                [a[s], a[i]] = [a[i], a[s]];
                i = s;
            }
        }
        return top;
    }
}

class MedianFinder {
    constructor() {
        this.lower = new _MinHeap();
        this.upper = new _MinHeap();
    }
    addNum(num) {
        this.lower.push(-num);
        this.upper.push(-this.lower.pop());
        if (this.upper.size() > this.lower.size()) {
            this.lower.push(-this.upper.pop());
        }
    }
    findMedian() {
        if (this.lower.size() > this.upper.size()) {
            return -this.lower.peek();
        }
        return (-this.lower.peek() + this.upper.peek()) / 2.0;
    }
}

